CREATE TABLE IF NOT EXISTS machines(id text PRIMARY KEY,name text NOT NULL,brand text NOT NULL,model text NOT NULL,location text NOT NULL,serial_number text,installed_at date);
CREATE TABLE IF NOT EXISTS components(id text PRIMARY KEY,machine_id text NOT NULL REFERENCES machines(id),name text NOT NULL,UNIQUE(id,machine_id));
CREATE TABLE IF NOT EXISTS devices(id text PRIMARY KEY,machine_id text NOT NULL REFERENCES machines(id),component_id text NOT NULL,FOREIGN KEY(component_id,machine_id) REFERENCES components(id,machine_id));
CREATE TABLE IF NOT EXISTS thresholds(component_id text PRIMARY KEY REFERENCES components(id),temperature_warning double precision NOT NULL DEFAULT 70,vibration_warning double precision NOT NULL DEFAULT 3.5,CHECK(temperature_warning BETWEEN 1 AND 200),CHECK(vibration_warning BETWEEN 0.1 AND 100));
CREATE TABLE IF NOT EXISTS measurements(id uuid PRIMARY KEY,device_id text NOT NULL REFERENCES devices(id),measured_at timestamptz NOT NULL,received_at timestamptz NOT NULL DEFAULT now(),temperature_c double precision NOT NULL CHECK(temperature_c BETWEEN -50 AND 200),vibration_rms_ms2 double precision NOT NULL CHECK(vibration_rms_ms2 BETWEEN 0 AND 100),source text NOT NULL CHECK(source IN ('device','simulation')));
CREATE INDEX IF NOT EXISTS measurements_device_time ON measurements(device_id,measured_at DESC);
CREATE TABLE IF NOT EXISTS alerts(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,component_id text NOT NULL REFERENCES components(id),variable text NOT NULL,value double precision NOT NULL,measured_at timestamptz NOT NULL,source text NOT NULL,level text NOT NULL DEFAULT 'warning',resolved_at timestamptz,acknowledged_at timestamptz,action_note text);
CREATE UNIQUE INDEX IF NOT EXISTS one_active_alert ON alerts(component_id,variable,source) WHERE resolved_at IS NULL;
CREATE TABLE IF NOT EXISTS app_users(id uuid PRIMARY KEY,email text UNIQUE NOT NULL,password_hash text NOT NULL,role text NOT NULL CHECK(role IN ('administrator','technician','supervisor','viewer')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS work_orders(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,component_id text NOT NULL REFERENCES components(id),alert_id bigint REFERENCES alerts(id),symptoms text NOT NULL,possible_cause text,confirmed_root_cause text,corrective_actions text,parts_used text,downtime_minutes integer CHECK(downtime_minutes>=0),responsible_user uuid REFERENCES app_users(id),status text NOT NULL DEFAULT 'open',created_at timestamptz NOT NULL DEFAULT now());
